export interface Item {
  sku: string;
  /** Unit price in cents. */
  price: number;
  quantity: number;
}

export class Cart {
  private items: Item[] = [];
  private discountMultiplier = 1;

  add(item: Item): void {
    this.items.push(item);
  }

  total(): number {
    return this.items.reduce((sum, item) => sum + item.price * item.quantity, 0) * this.discountMultiplier;
  }

  applyDiscount(code: string): void {
    this.discountMultiplier = 0.9;
  }
}
